ttps.validationKql:
let Seed = OfficeActivity | where Operation == "Set-Mailbox" and tostring(Parameters) has "ForwardingSmtpAddress" | project AccountId=UserId, IPAddress=ClientIP;
let App = CloudAppEvents | where ActionType == "MailboxForwardingConfigured" | project AccountId, IPAddress, OAuthAppId | join kind=inner Seed on AccountId, IPAddress | project OAuthAppId, IPAddress;
AADServicePrincipalSignInLogs | project OAuthAppId=AppId, IPAddress, Flag=UserAgent | join kind=inner App on OAuthAppId, IPAddress | project Flag

let Seed = OfficeActivity | where Operation == "New-InboxRule" and tostring(Parameters) has_any ("DeleteMessage", "MoveToFolder") | project UserPrincipalName=UserId, IPAddress=ClientIP;
let Auth = SigninLogs | where AppDisplayName == "Office 365 Exchange Online" and isnotempty(SessionId) | project UserPrincipalName, IPAddress, SessionId | join kind=inner Seed on UserPrincipalName, IPAddress | project SessionId;
AADNonInteractiveUserSignInLogs | where isnotempty(SessionId) | project SessionId, Flag=AuthenticationDetails | join kind=inner Auth on SessionId | project Flag

let Seed = OfficeActivity | where Operation == "Add-MailboxPermission" and tostring(Parameters) has_any ("FullAccess", "SendAs", "SendOnBehalf") | extend DelegateUpn=extract(@"User=([^;]+)", 1, tostring(Parameters)) | project DelegateUpn, IPAddress=ClientIP;
let Session = CloudAppEvents | where ActionType == "MailboxPermissionGranted" | extend SessionId=tostring(SessionData.SessionId) | project DelegateUpn=AccountId, IPAddress, SessionId | join kind=inner Seed on DelegateUpn, IPAddress | project SessionId;
AADNonInteractiveUserSignInLogs | project SessionId, Flag=AuthenticationDetails | join kind=inner Session on SessionId | project Flag

let Audit = AuditLogs | where OperationName == "Add app role assignment to service principal" and tostring(AdditionalDetails) has_all ("Mail.Read", "Files.Read.All") | extend OAuthAppId=tostring(TargetResources[0].appId) | project AuditCorrelationId=tostring(CorrelationId), OAuthAppId;
let Grant = CloudAppEvents | where ActionType == "OAuthAppPermissionGranted" | extend AuditCorrelationId=tostring(RawEventData.AuditCorrelationId) | project AuditCorrelationId, OAuthAppId, IPAddress | join kind=inner Audit on AuditCorrelationId, OAuthAppId | project OAuthAppId, IPAddress;
AADServicePrincipalSignInLogs | project OAuthAppId=AppId, IPAddress, Flag=UserAgent | join kind=inner Grant on OAuthAppId, IPAddress | project Flag

let Role = AuditLogs | where OperationName == "Add member to role" and tostring(TargetResources) has "Global Administrator" | extend UserId=tostring(TargetResources[0].id), IPAddress=tostring(InitiatedBy.user.ipAddress) | project UserId, IPAddress;
let Session = SigninLogs | where AppDisplayName == "Azure Portal" | project UserId, IPAddress, SessionId | join kind=inner Role on UserId, IPAddress | project SessionId;
AADNonInteractiveUserSignInLogs | project SessionId, Flag=AuthenticationDetails | join kind=inner Session on SessionId | project Flag

let Role = AuditLogs | where OperationName == "Add app role assignment to service principal" and tostring(AdditionalDetails) has "RoleManagement.ReadWrite.Directory" | extend ServicePrincipalId=tostring(TargetResources[0].id) | project ServicePrincipalId;
let Token = AADServicePrincipalSignInLogs | project ServicePrincipalId, UniqueTokenIdentifier | join kind=inner Role on ServicePrincipalId | project UniqueTokenIdentifier;
GraphAPIAuditEvents | project UniqueTokenIdentifier, Flag=RequestUri | join kind=inner Token on UniqueTokenIdentifier | project Flag

let Audit = AuditLogs | where OperationName == "Update conditional access policy" | project AuditCorrelationId=tostring(CorrelationId);
let Policy = CloudAppEvents | extend AuditCorrelationId=tostring(RawEventData.AuditCorrelationId) | project AuditCorrelationId, PolicyId=tostring(ObjectId) | join kind=inner Audit on AuditCorrelationId | project PolicyId;
SigninLogs | mv-expand EvaluatedPolicy=ConditionalAccessPolicies | project PolicyId=tostring(EvaluatedPolicy.id), Flag=AuthenticationDetails | join kind=inner Policy on PolicyId | project Flag

let Recon = IdentityQueryEvents | where QueryType == "EnumerateUsers" and Query has "adminCount=1" | project UserId=AccountObjectId, IPAddress;
let Token = SigninLogs | project UserId, IPAddress, UniqueTokenIdentifier | join kind=inner Recon on UserId, IPAddress | project UniqueTokenIdentifier;
GraphAPIAuditEvents | project UniqueTokenIdentifier, Flag=RequestUri | join kind=inner Token on UniqueTokenIdentifier | project Flag

let Auth = SigninLogs | where ResultType == "0" and IsInteractive and AppDisplayName == "Microsoft 365" | project SessionId;
let Activity = CloudAppEvents | extend SessionId=tostring(SessionData.SessionId) | project SessionId | join kind=inner Auth on SessionId | distinct SessionId;
AADNonInteractiveUserSignInLogs | where not(IsInteractive) | project SessionId, Flag=AuthenticationDetails | join kind=inner Activity on SessionId | project Flag

let Guest = AuditLogs | where OperationName == "Add member to group" and tostring(TargetResources) has_all ("Guest", "Incident Response Administrators") | extend GuestUserId=tostring(TargetResources[0].id) | project GuestUserId;
let Session = SigninLogs | where HomeTenantId != ResourceTenantId and CrossTenantAccessType == "b2bCollaboration" | project GuestUserId=UserId, SessionId | join kind=inner Guest on GuestUserId | project SessionId;
CloudAppEvents | where IsExternalUser | extend SessionId=tostring(SessionData.SessionId) | project SessionId, Flag=RawEventData | join kind=inner Session on SessionId | project Flag

let Identity = SigninLogs | where ResultType == "0" and AppDisplayName == "Azure Portal" | project Caller=UserPrincipalName, CallerIpAddress=IPAddress;
let Command = AzureActivity | where OperationNameValue =~ "MICROSOFT.COMPUTE/VIRTUALMACHINES/RUNCOMMAND/ACTION" | project Caller, CallerIpAddress, ResourceKey=tolower(tostring(Resource)) | join kind=inner Identity on Caller, CallerIpAddress | project ResourceKey;
DeviceProcessEvents | where FolderPath has "RunCommandWindows" | extend ResourceKey=tolower(tostring(split(DeviceName, ".")[0])) | project ResourceKey, Flag=ProcessCommandLine | join kind=inner Command on ResourceKey | project Flag

let Consent = AuditLogs | where OperationName == "Consent to application" and tostring(AdditionalDetails) has_all ("Files.Read.All", "Directory.Read.All") | extend ServicePrincipalId=tostring(TargetResources[0].id) | project ServicePrincipalId;
let Token = AADServicePrincipalSignInLogs | project ServicePrincipalId, UniqueTokenIdentifier | join kind=inner Consent on ServicePrincipalId | project UniqueTokenIdentifier;
GraphAPIAuditEvents | project UniqueTokenIdentifier, Flag=RequestUri | join kind=inner Token on UniqueTokenIdentifier | project Flag

let Auth = SigninLogs | where ResultType == "0" and AuthenticationProcessingDetails has "On-Behalf-Of" | project SessionId;
let Token = AADNonInteractiveUserSignInLogs | where AuthenticationProtocol == "oAuth2" | project SessionId, UniqueTokenIdentifier | join kind=inner Auth on SessionId | project UniqueTokenIdentifier;
GraphAPIAuditEvents | project UniqueTokenIdentifier, Flag=RequestUri | join kind=inner Token on UniqueTokenIdentifier | project Flag

let SignIn = AADServicePrincipalSignInLogs | where AppOwnerTenantId != AADTenantId | project AppId, UniqueTokenIdentifier;
let Api = GraphAPIAuditEvents | project AppId=ApplicationId, UniqueTokenIdentifier, ReportId | join kind=inner SignIn on AppId, UniqueTokenIdentifier | project AppId, ReportId;
CloudAppEvents | project AppId=OAuthAppId, ReportId, Flag=RawEventData | join kind=inner Api on AppId, ReportId | project Flag

let Consent = AuditLogs | where OperationName == "Consent to application" and tostring(AdditionalDetails) has_all ("Principal", "Mail.Read", "offline_access") | project AuditCorrelationId=tostring(CorrelationId);
let Session = CloudAppEvents | where ActionType == "OAuthAppConsentGranted" | extend AuditCorrelationId=tostring(RawEventData.AuditCorrelationId), SessionId=tostring(SessionData.SessionId) | project AuditCorrelationId, SessionId | join kind=inner Consent on AuditCorrelationId | project SessionId;
AADNonInteractiveUserSignInLogs | where IncomingTokenType == "refreshToken" | project SessionId, Flag=AuthenticationDetails | join kind=inner Session on SessionId | project Flag

let Enumeration = AzureActivity | where OperationNameValue contains "/LIST" or OperationNameValue contains "/READ" | summarize Operations=make_set(OperationNameValue), Providers=dcount(ResourceProviderValue), FirstSeen=min(TimeGenerated), LastSeen=max(TimeGenerated) by Caller, CallerIpAddress, WindowStart=bin(TimeGenerated, 5m) | where array_length(Operations) >= 3 and Providers >= 3 and LastSeen - FirstSeen <= 2m | project Caller, CallerIpAddress;
let Session = SigninLogs | where AppDisplayName == "Microsoft Azure CLI" | project Caller=UserPrincipalName, CallerIpAddress=IPAddress, SessionId | join kind=inner Enumeration on Caller, CallerIpAddress | project SessionId;
AADNonInteractiveUserSignInLogs | project SessionId, Flag=AuthenticationDetails | join kind=inner Session on SessionId | project Flag

let FileAccess = CloudAppEvents | where ActionType == "FileAccessed" and AccountType == "ServicePrincipal" | project AppId=OAuthAppId, ObjectId;
let Api = GraphAPIAuditEvents | extend ObjectId=extract(@"/drive/items/([^/]+)/content", 1, RequestUri) | project AppId=ApplicationId, ObjectId | join kind=inner FileAccess on AppId, ObjectId | project ObjectId;
OfficeActivity | where Operation == "FileDownloaded" | project ObjectId=OfficeObjectId, Flag=SourceFileName | join kind=inner Api on ObjectId | project Flag
